import{_ as n,o as a,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"rewrite、return 与 if","description":"四个 flag 的精确差异、rewrite 阶段的执行时机、「if is evil」的真实含义与安全替代。","frontmatter":{"title":"rewrite、return 与 if","description":"四个 flag 的精确差异、rewrite 阶段的执行时机、「if is evil」的真实含义与安全替代。","source":"https://daiw.org/manual/nginx/rewrite"},"headers":[],"relativePath":"manual/tools/nginx/rewrite.md","filePath":"manual/tools/nginx/rewrite.md"}'),l={name:"manual/tools/nginx/rewrite.md"};function i(r,s,t,c,o,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="rewrite、return-与-if" tabindex="-1">rewrite、return 与 if <a class="header-anchor" href="#rewrite、return-与-if" aria-label="Permalink to &quot;rewrite、return 与 if&quot;">​</a></h1><p><code>ngx_http_rewrite_module</code> 提供 <code>rewrite</code>、<code>return</code>、<code>set</code>、<code>if</code>、<code>break</code> 五条指令。它们<strong>不是按书写顺序简单执行的</strong>——理解「rewrite 阶段」是用对它们的前提。</p><h2 id="return" tabindex="-1">return <a class="header-anchor" href="#return" aria-label="Permalink to &quot;return&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    return code [text];</span></span>
<span class="line"><span>         return code URL;</span></span>
<span class="line"><span>         return URL;</span></span>
<span class="line"><span>上下文:  server, location, if</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>最简单也最该优先用的一条</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>return 301 https://$host$request_uri;    # 永久重定向</span></span>
<span class="line"><span>return 404;                              # 状态码</span></span>
<span class="line"><span>return 200 &quot;OK\\n&quot;;                       # 状态码 + 文本</span></span>
<span class="line"><span>return 444;                              # nginx 私有：直接断连</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>return</code> <strong>立即终止处理</strong>，不再执行后续指令。</p><p>带文本时可以指定类型：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location = /healthz {</span></span>
<span class="line"><span>    default_type text/plain;</span></span>
<span class="line"><span>    return 200 &quot;ok\\n&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>能用 <code>return</code> 就不要用 <code>rewrite</code>。</strong> 它更快（无正则匹配）、语义更明确、没有阶段陷阱。</p><p>域名跳转的正确写法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 80;</span></span>
<span class="line"><span>    server_name example.com;</span></span>
<span class="line"><span>    return 301 https://$host$request_uri;   # ✅</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>而不是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite ^(.*)$ https://$host$1 permanent;   # ❌ 更慢，且丢查询参数需另处理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>301</code>/<code>302</code>/<code>303</code>/<code>307</code>/<code>308</code> 的语义差别见 <a href="https://daiw.org/manual/http11/status-3xx" target="_blank" rel="noreferrer">HTTP 3xx 章节</a>——尤其注意 <code>301</code>/<code>302</code> 会改写方法而 <code>307</code>/<code>308</code> 不会。</p><h2 id="rewrite" tabindex="-1">rewrite <a class="header-anchor" href="#rewrite" aria-label="Permalink to &quot;rewrite&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    rewrite regex replacement [flag];</span></span>
<span class="line"><span>上下文:  server, location, if</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite ^/old/(.*)$ /new/$1 last;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="四个-flag" tabindex="-1">四个 flag <a class="header-anchor" href="#四个-flag" aria-label="Permalink to &quot;四个 flag&quot;">​</a></h3><table tabindex="0"><thead><tr><th>flag</th><th>行为</th></tr></thead><tbody><tr><td>（无）</td><td>继续执行<strong>后续 rewrite 指令</strong></td></tr><tr><td><code>last</code></td><td><strong>停止当前 rewrite 集，用新 URI 重新搜索 location</strong></td></tr><tr><td><code>break</code></td><td><strong>停止当前 rewrite 集，不重新搜索 location</strong></td></tr><tr><td><code>redirect</code></td><td>返回 <strong>302</strong> 临时重定向</td></tr><tr><td><code>permanent</code></td><td>返回 <strong>301</strong> 永久重定向</td></tr></tbody></table><p><strong><code>last</code> 与 <code>break</code> 的区别是全篇最关键的一点</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>last   → 改写 URI → 回到 location 匹配阶段，重新找 location</span></span>
<span class="line"><span>break  → 改写 URI → 留在当前 location 继续处理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /a/ {</span></span>
<span class="line"><span>    rewrite ^/a/(.*)$ /b/$1 last;    # 会去匹配 location /b/</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>location /a/ {</span></span>
<span class="line"><span>    rewrite ^/a/(.*)$ /b/$1 break;   # 留在 location /a/ 里，用新 URI 取文件</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong><code>last</code> 有循环风险。</strong> 每次 <code>last</code> 都会重新走一遍 location 匹配，规则写得不好会无限循环。nginx 的内部重定向上限是 <strong>10 次</strong>，超过返回 <code>500</code> 并记录：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite or internal redirection cycle while processing &quot;/xxx&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这与 <a href="/Front2Full/manual/tools/nginx/root-alias"><code>try_files</code> 的循环</a>是同一个计数器。</p><p><code>replacement</code> 以 <code>http://</code>、<code>https://</code>、<code>$scheme</code> 开头时，<strong>自动变成重定向</strong>（不需要写 flag）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite ^/old$ https://example.com/new;   # 自动 302</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="查询参数的处理" tabindex="-1">查询参数的处理 <a class="header-anchor" href="#查询参数的处理" aria-label="Permalink to &quot;查询参数的处理&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rewrite ^/old/(.*)$ /new/$1;        # 原查询串会被自动附加</span></span>
<span class="line"><span>rewrite ^/old/(.*)$ /new/$1?;       # 结尾的 ? 丢弃原查询串</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认会保留原查询参数</strong>。结尾加 <code>?</code> 才丢弃。</p><h2 id="rewrite-阶段的执行时机" tabindex="-1">rewrite 阶段的执行时机 <a class="header-anchor" href="#rewrite-阶段的执行时机" aria-label="Permalink to &quot;rewrite 阶段的执行时机&quot;">​</a></h2><p>这是理解一切诡异行为的钥匙。nginx 处理请求分多个阶段，rewrite 模块的指令在 <strong><code>server</code> 级的 rewrite 阶段</strong>与 <strong><code>location</code> 级的 rewrite 阶段</strong>执行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. server 级 rewrite 指令        ← 此时还没选 location！</span></span>
<span class="line"><span>2. location 匹配</span></span>
<span class="line"><span>3. location 级 rewrite 指令</span></span>
<span class="line"><span>4. try_files / index</span></span>
<span class="line"><span>5. 内容生成（proxy_pass / root 等）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>由此推出两条重要结论：</p><p><strong>一、server 级的 <code>rewrite</code> 在 location 选择之前执行。</strong> 所以它改写的 URI 会影响后续 location 匹配——这是它的正确用途。</p><p><strong>二、<code>set</code> 也在 rewrite 阶段。</strong> 所以下面这段的行为可能反直觉：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location / {</span></span>
<span class="line"><span>    set $x &quot;A&quot;;</span></span>
<span class="line"><span>    return 200 $x;      # 输出 A</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>但如果 <code>set</code> 写在 <code>if</code> 里，就要小心了。</p><h2 id="if-is-evil" tabindex="-1">if is evil <a class="header-anchor" href="#if-is-evil" aria-label="Permalink to &quot;if is evil&quot;">​</a></h2><p>nginx 官方 wiki 有一篇著名的 <a href="https://www.nginx.com/resources/wiki/start/topics/depth/ifisevil/" target="_blank" rel="noreferrer">If Is Evil</a>。核心结论：</p><blockquote><p><strong>在 <code>location</code> 内部，<code>if</code> 只有用于 <code>return</code> 和 <code>rewrite ... last</code> 时是 100% 安全的。</strong></p></blockquote><p>其他用法可能产生不可预期的行为。</p><h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><p><code>if</code> 会创建一个<strong>隐式的嵌套 location</strong>，配置继承与执行顺序变得难以推理。经典反例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /x/ {</span></span>
<span class="line"><span>    set $a 1;</span></span>
<span class="line"><span>    if ($request_method = POST) {</span></span>
<span class="line"><span>        set $a 2;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if ($http_x_test) {</span></span>
<span class="line"><span>        set $a 3;        # 两个 if 都成立时，结果未必是你想的</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 200 $a;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>更危险的是与 <code>proxy_pass</code> 混用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /x/ {</span></span>
<span class="line"><span>    proxy_pass http://backend;</span></span>
<span class="line"><span>    if ($http_x_flag) {</span></span>
<span class="line"><span>        add_header X-Flag 1;   # ← 这会让 proxy_pass 失效或行为异常</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>if</code> 块内没有 <code>proxy_pass</code>，请求进了 if 创建的隐式 location 后<strong>可能找不到内容处理器</strong>，导致返回空响应或 404。</p><h3 id="安全用法" tabindex="-1">安全用法 <a class="header-anchor" href="#安全用法" aria-label="Permalink to &quot;安全用法&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ✅ 安全：if + return</span></span>
<span class="line"><span>if ($request_method = POST) {</span></span>
<span class="line"><span>    return 405;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 安全：if + rewrite ... last</span></span>
<span class="line"><span>if ($http_user_agent ~* &quot;bot&quot;) {</span></span>
<span class="line"><span>    rewrite ^ /bot-page last;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ❌ 危险：if + 其他任何指令</span></span>
<span class="line"><span>if ($x) {</span></span>
<span class="line"><span>    proxy_pass ...;    # 不要</span></span>
<span class="line"><span>    add_header ...;    # 不要</span></span>
<span class="line"><span>    set ...;           # 尽量不要</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h3 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to &quot;替代方案&quot;">​</a></h3><p>大多数 <code>if</code> 都能用 <a href="/Front2Full/manual/tools/nginx/map-geo"><code>map</code></a> 替代：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ if</span></span>
<span class="line"><span>if ($http_user_agent ~* &quot;(bot|spider)&quot;) {</span></span>
<span class="line"><span>    set $is_bot 1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ map（在 http 上下文，无副作用）</span></span>
<span class="line"><span>map $http_user_agent $is_bot {</span></span>
<span class="line"><span>    default          0;</span></span>
<span class="line"><span>    ~*(bot|spider)   1;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><code>map</code> 在 <code>http</code> 上下文定义，<strong>惰性求值、无执行顺序问题</strong>，是 nginx 里表达条件逻辑的正确工具。</p><p>按方法路由用 <code>limit_except</code> 或独立 location：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /api/ {</span></span>
<span class="line"><span>    limit_except GET { deny all; }</span></span>
<span class="line"><span>    proxy_pass http://backend;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="set" tabindex="-1">set <a class="header-anchor" href="#set" aria-label="Permalink to &quot;set&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    set $variable value;</span></span>
<span class="line"><span>上下文:  server, location, if</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set $backend &quot;http://app1&quot;;</span></span>
<span class="line"><span>set $combined &quot;$host$request_uri&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>在 rewrite 阶段执行。可以引用其他变量。</p><p>注意它<strong>不能覆盖内置变量</strong>（如 <code>$uri</code>、<code>$args</code> 部分可写，多数只读）。</p><h2 id="break" tabindex="-1">break <a class="header-anchor" href="#break" aria-label="Permalink to &quot;break&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    break;</span></span>
<span class="line"><span>上下文:  server, location, if</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>单独的 <code>break</code> 指令停止执行<strong>当前 rewrite 指令集</strong>，与 <code>rewrite ... break</code> 的效果相同但不改写 URI。</p><h2 id="常见场景写法" tabindex="-1">常见场景写法 <a class="header-anchor" href="#常见场景写法" aria-label="Permalink to &quot;常见场景写法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. HTTP → HTTPS：用 return</span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    listen 80;</span></span>
<span class="line"><span>    server_name example.com www.example.com;</span></span>
<span class="line"><span>    return 301 https://$host$request_uri;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    server_name example.com www.example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 2. www → 裸域：用 if + return（安全用法）</span></span>
<span class="line"><span>    if ($host = www.example.com) {</span></span>
<span class="line"><span>        return 301 https://example.com$request_uri;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 3. 旧路径迁移：server 级 rewrite，影响后续 location 匹配</span></span>
<span class="line"><span>    rewrite ^/blog/(.*)$ /posts/$1 permanent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 4. 内部改写：break 留在当前 location</span></span>
<span class="line"><span>    location /files/ {</span></span>
<span class="line"><span>        rewrite ^/files/(.*)$ /storage/$1 break;</span></span>
<span class="line"><span>        root /var/data;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 5. 条件逻辑：用 map 不用 if</span></span>
<span class="line"><span>    location /api/ {</span></span>
<span class="line"><span>        proxy_pass http://$backend_pool;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>map $http_x_canary $backend_pool {</span></span>
<span class="line"><span>    default  &quot;stable&quot;;</span></span>
<span class="line"><span>    &quot;1&quot;      &quot;canary&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/map-geo">map、geo 与 split_clients</a>。</p>`,68)])])}const m=n(l,[["render",i]]);export{u as __pageData,m as default};
